import {
  Box,
  Stack,
  Typography,
} from "@mui/material";

import {
  TrendingUpRounded,
} from "@mui/icons-material";

import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import {
  ForecastFilters,
  ForecastScenarioRecord,
  ForecastScenarioApiResponse,
} from "../types/forecast.types";

import {
  useQuery,
} from "@tanstack/react-query";

import forecastService from "../service/forecast.service";


interface ScenarioComparisonProps {
  filters: ForecastFilters;
}


interface ScenarioPoint {
  scenario: string;
  scenarioId: string;
  value: number;
}


const ScenarioComparison = ({
  filters,
}: ScenarioComparisonProps) => {

  const {
    data,
    isLoading,
    isError,
  } = useQuery<ForecastScenarioApiResponse>({
    queryKey: [
      "scenario-comparison",
      filters.horizon,
      filters.entityId,
      filters.metric,
    ],

    queryFn: () =>
      forecastService.getScenarioData(),

    staleTime: 5 * 60 * 1000,
  });


  /*
   * ------------------------------------------------------
   * METRIC VALUE
   * ------------------------------------------------------
   */

  const getMetricValue = (
    record: ForecastScenarioRecord
  ): number => {

    switch (filters.metric) {

      case "burn":
        return Number(
          record.Input
        );

      case "supply":
        return Number(
          record.Replenishment
        );

      case "stockpile":
        return Number(
          record.Stockpile
        );

      default:
        return Number(
          record.Input
        );
    }
  };


  /*
   * ------------------------------------------------------
   * LABELS
   * ------------------------------------------------------
   */

  const getMetricLabel = (): string => {

    switch (filters.metric) {

      case "burn":
        return "Burn";

      case "supply":
        return "Supply";

      case "stockpile":
        return "Stockpile";

      default:
        return "Forecast";
    }
  };


  const getMetricUnit = (): string => {

    if (
      filters.metric === "stockpile"
    ) {
      return "tonnes";
    }

    if (
      filters.horizon === "daily"
    ) {
      return "t/day";
    }

    return "tonnes";
  };


  /*
   * ------------------------------------------------------
   * SCENARIO DISPLAY NAMES
   * ------------------------------------------------------
   */

  const scenarioLabels: Record<
    string,
    string
  > = {

    actual:
      "Actual",

    weather_hot_dry:
      "Hot & Dry",

    weather_hot_wet:
      "Hot & Wet",

    weather_cold_dry:
      "Cold & Dry",

    weather_cold_wet:
      "Cold & Wet",
  };


  /*
   * ------------------------------------------------------
   * SCENARIO COLORS
   * ------------------------------------------------------
   */

  const scenarioColors: Record<
    string,
    string
  > = {

    actual:
      "#1264FF",

    weather_hot_dry:
      "#F57C00",

    weather_hot_wet:
      "#D32F2F",

    weather_cold_dry:
      "#455A64",

    weather_cold_wet:
      "#2E7D32",
  };


  /*
   * ------------------------------------------------------
   * SCENARIOS TO DISPLAY
   * ------------------------------------------------------
   */

  const scenarioIds: string[] = [
    "actual",
    "weather_hot_dry",
    "weather_hot_wet",
    "weather_cold_dry",
    "weather_cold_wet",
  ];


  /*
   * ------------------------------------------------------
   * SELECT HORIZON
   * ------------------------------------------------------
   */

  const source: ForecastScenarioRecord[] =
    data
      ? filters.horizon === "monthly"
        ? data.monthly
        : data.daily
      : [];


  /*
   * ------------------------------------------------------
   * BUILD CHART DATA
   * ------------------------------------------------------
   */

  const chartData: ScenarioPoint[] =
    scenarioIds.map(
      (
        scenarioId: string
      ): ScenarioPoint => {

        const records: ForecastScenarioRecord[] =
          source.filter(
            (
              record: ForecastScenarioRecord
            ): boolean =>
              record.entity_id ===
                filters.entityId &&
              record.scenario_id ===
                scenarioId
          );


        const values: number[] =
          records.map(
            (
              record: ForecastScenarioRecord
            ): number =>
              getMetricValue(
                record
              )
          );


        const average =
          values.length > 0
            ? values.reduce(
                (
                  sum: number,
                  value: number
                ): number =>
                  sum + value,
                0
              ) /
              values.length
            : 0;


        return {
          scenario:
            scenarioLabels[
              scenarioId
            ] ??
            scenarioId,

          scenarioId,

          value:
            average,
        };
      }
    );


  /*
   * ------------------------------------------------------
   * FORMAT NUMBERS
   * ------------------------------------------------------
   */

  const formatNumber = (
    value: number
  ): string => {

    return new Intl.NumberFormat(
      "en-US",
      {
        maximumFractionDigits: 1,
      }
    )
      .format(value)
      .replace(
        /,/g,
        " "
      );
  };


  /*
   * ------------------------------------------------------
   * LOADING
   * ------------------------------------------------------
   */

  if (isLoading) {

    return (
      <Box
        sx={{
          bgcolor:
            "background.paper",

          border:
            "1px solid",

          borderColor:
            "divider",

          borderRadius: 4,

          p: {
            xs: 2.5,
            md: 4,
          },
        }}
      >
        <Box
          sx={{
            minHeight: 340,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <Typography
            color="text.secondary"
          >
            Loading scenario comparison...
          </Typography>
        </Box>
      </Box>
    );
  }


  /*
   * ------------------------------------------------------
   * ERROR
   * ------------------------------------------------------
   */

  if (isError) {

    return (
      <Box
        sx={{
          bgcolor:
            "background.paper",

          border:
            "1px solid",

          borderColor:
            "divider",

          borderRadius: 4,

          p: {
            xs: 2.5,
            md: 4,
          },
        }}
      >
        <Typography
          color="error"
        >
          Unable to load scenario data.
        </Typography>
      </Box>
    );
  }


  /*
   * ------------------------------------------------------
   * RENDER
   * ------------------------------------------------------
   */

  return (
    <Box
      sx={{
        bgcolor:
          "background.paper",

        border:
          "1px solid",

        borderColor:
          "divider",

        borderRadius: 4,

        p: {
          xs: 2.5,
          md: 4,
        },

        width: "100%",
        minWidth: 0,

        overflow: "hidden",
      }}
    >

      {/* HEADER */}

      <Stack
        direction={{
          xs: "column",
          sm: "row",
        }}
        justifyContent="space-between"
        alignItems={{
          xs: "flex-start",
          sm: "center",
        }}
        spacing={2}
        mb={4}
      >

        <Box>

          <Typography
            variant="h5"
            fontWeight={800}
            color="#172B4D"
          >
            Scenario Comparison
          </Typography>

          <Typography
            variant="body2"
            color="text.secondary"
            mt={0.75}
          >
            Average projected{" "}
            {getMetricLabel().toLowerCase()}{" "}
            under each weather scenario.
          </Typography>

        </Box>


        <Stack
          direction="row"
          spacing={1}
          alignItems="center"
          sx={{
            flexShrink: 0,
          }}
        >

          <TrendingUpRounded
            sx={{
              color: "#1264FF",
            }}
          />

          <Typography
            variant="body2"
            fontWeight={700}
            color="#172B4D"
          >
            {getMetricUnit()}
          </Typography>

        </Stack>

      </Stack>


      {/* CHART */}

      <Box
        sx={{
          width: "100%",
          height: {
            xs: 320,
            sm: 360,
            md: 400,
          },

          minWidth: 0,
        }}
      >

        <ResponsiveContainer
          width="100%"
          height="100%"
        >

          <BarChart
            data={chartData}
            layout="vertical"
            margin={{
              top: 5,
              right: 40,
              left: 10,
              bottom: 5,
            }}
          >

            <CartesianGrid
              strokeDasharray="4 6"
              horizontal={false}
              stroke="#E8ECF2"
            />


            <XAxis
              type="number"
              tick={{
                fill: "#6B778C",
                fontSize: 12,
              }}
              axisLine={false}
              tickLine={false}
              tickFormatter={(
                value: number
              ) =>
                formatNumber(value)
              }
            />


            <YAxis
              type="category"
              dataKey="scenario"
              width={105}
              tick={{
                fill: "#172B4D",
                fontSize: 12,
                fontWeight: 600,
              }}
              axisLine={false}
              tickLine={false}
            />


            <Tooltip
              formatter={(
                value: number
              ) => [
                `${formatNumber(
                  value
                )} ${getMetricUnit()}`,
                getMetricLabel(),
              ]}
              contentStyle={{
                borderRadius: 12,
                border:
                  "1px solid #E3E8EF",
                boxShadow:
                  "0 10px 30px rgba(0,0,0,0.08)",
              }}
            />


            <Bar
              dataKey="value"
              radius={[
                0,
                8,
                8,
                0,
              ]}
              barSize={36}
            >

              {chartData.map(
                (
                  entry: ScenarioPoint
                ) => (

                  <Cell
                    key={
                      entry.scenarioId
                    }
                    fill={
                      scenarioColors[
                        entry.scenarioId
                      ] ??
                      "#1264FF"
                    }
                  />

                )
              )}

            </Bar>

          </BarChart>

        </ResponsiveContainer>

      </Box>

    </Box>
  );
};


export default ScenarioComparison;
